using Microsoft.AspNetCore.Mvc;
using TvWeb.Data;

namespace TvWeb.Controllers;

[Route("phim")]
public class PhimController : Controller
{
    private readonly AppDb _db;
    public PhimController(AppDb db) => _db = db;

    [HttpGet("")]
    public async Task<IActionResult> Index(string? q, string? genre, string? status, int page = 1, int size = 24)
    {
        page = Math.Max(1, page);
        var films = await _db.SearchAsync(q, genre, status, page, size);
        var total = await _db.CountAsync(q, genre, status);
        ViewBag.Genres = await _db.GenresAsync();
        ViewBag.Query = q; ViewBag.Genre = genre; ViewBag.Status = status;
        ViewBag.Page = page; ViewBag.Size = size; ViewBag.Total = total;
        return View(films);
    }

    [HttpGet("{slug}")]
    public async Task<IActionResult> Details(string slug)
    {
        var film = await _db.GetFilmAsync(slug);
        if (film == null) return NotFound();
        var eps = await _db.GetEpisodesAsync(slug);
        return View((film, eps));
    }

    // /xem-phim/{slug}?server=..&ep=..
    [HttpGet("/xem-phim/{slug}")]
    public async Task<IActionResult> Xem(string slug, string? server, string? ep)
    {
        var film = await _db.GetFilmAsync(slug);
        if (film == null) return NotFound();
        var eps = await _db.GetEpisodesAsync(slug);
        if (eps.Count == 0) return View("NoSource", film);
        var servers = eps.Select(e => e.ServerSlug).Distinct().ToList();
        server ??= servers.First();
        var list = eps.Where(e => e.ServerSlug == server).ToList();
        if (list.Count == 0) { server = servers.First(); list = eps.Where(e => e.ServerSlug == server).ToList(); }
        ep ??= list.First().EpIndex;
        var cur = list.FirstOrDefault(e => e.EpIndex == ep) ?? list.First();
        ViewBag.Servers = servers; ViewBag.Server = server; ViewBag.Ep = cur.EpIndex;
        return View((film, eps, cur));
    }
}

using Microsoft.AspNetCore.Mvc;
using TvWeb.Data;

namespace TvWeb.Controllers;

[Route("api")]
[ApiController]
public class ApiController : ControllerBase
{
    private readonly AppDb _db;
    public ApiController(AppDb db) => _db = db;

    [HttpGet("phims/moi")]
    public async Task<IActionResult> Moi([FromQuery] int take = 24) =>
        Ok(await _db.LatestAsync(Math.Clamp(take, 1, 100)));

    [HttpGet("phim/{slug}")]
    public async Task<IActionResult> ChiTiet(string slug)
    {
        var f = await _db.GetFilmAsync(slug);
        if (f == null) return NotFound();
        return Ok(new { film = f, episodes = await _db.GetEpisodesAsync(slug) });
    }
}

using TvWeb.Data;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddControllersWithViews();
builder.Services.AddSingleton<AppDb>();

var app = builder.Build();

// Ensure SQLite schema exists (shared DB with crawler)
using (var scope = app.Services.CreateScope())
{
    await scope.ServiceProvider.GetRequiredService<AppDb>().EnsureSchemaAsync();
}

