@model List<TvWeb.Models.Film>
@{ ViewData["Title"] = "Khám phá"; var total = (int)ViewBag.Total; var page = (int)ViewBag.Page; var size = (int)ViewBag.Size; var pages = (int)Math.Ceiling(total / (double)size); var genres = (List<string>)ViewBag.Genres; }
<div class="container-fluid px-3 px-lg-4 mt-3">
  <form class="row g-2 mb-3" method="get">
    <div class="col-12 col-md-4"><input class="form-control" name="q" value="@ViewBag.Query" placeholder="Tên phim..." /></div>
    <div class="col-6 col-md-3"><select class="form-select" name="genre"><option value="">Tất cả thể loại</option>@foreach (var g in genres) { <option selected="@(ViewBag.Genre == g)" value="@g">@g</option> }</select></div>
    <div class="col-6 col-md-3"><select class="form-select" name="status"><option value="">Lẻ + Bộ</option><option selected="@(ViewBag.Status=="phim-le")" value="phim-le">Phim lẻ</option><option selected="@(ViewBag.Status=="phim-bo")" value="phim-bo">Phim bộ</option></select></div>
    <div class="col-12 col-md-2"><button class="btn btn-danger w-100">Lọc</button></div>
  </form>
  <div class="film-grid">
    @foreach (var f in Model) { <partial name="_FilmCard" model="f" /> }
  </div>
  @if (pages > 1) { <nav class="mt-3"><ul class="pagination justify-content-center">
    @for (int i = 1; i <= Math.Min(pages, 20); i++) { <li class="page-item @(i==page?"active":"")"><a class="page-link" href="/phim?q=@ViewBag.Query&genre=@ViewBag.Genre&status=@ViewBag.Status&page=@i">@i</a></li> }
  </ul></nav> }
</div>

@model (TvWeb.Models.Film Film, List<TvWeb.Models.Episode> Eps)
@{ ViewData["Title"] = Model.Film.TitleVi; var servers = Model.Eps.Select(e => e.ServerSlug).Distinct().ToList(); }
<div class="container-fluid px-3 px-lg-4 mt-3">
  <div class="row g-4">
    <div class="col-12 col-md-3"><img class="detail-poster" src="@Model.Film.Poster" alt="@Model.Film.TitleVi" /></div>
    <div class="col-12 col-md-9">
      <h2>@Model.Film.TitleVi</h2>
      <p class="text-secondary">@Model.Film.TitleEn (@Model.Film.Year) • IMDb @(Model.Film.Imdb?.ToString() ?? "-") • @Model.Film.Quality • @Model.Film.Lang • @Model.Film.Country</p>
      <p>@foreach (var g in Model.Film.GenreList) { <a class="badge bg-secondary me-1" href="/phim?genre=@g">@g</a> }</p>
      <p class="desc">@Model.Film.Description</p>
      @if (Model.Eps.Count > 0) {
        <a class="btn btn-danger btn-lg" href="/xem-phim/@Model.Film.Slug">▶ Xem ngay</a>
        <h5 class="mt-4">Máy chủ & tập phim</h5>
        @foreach (var s in servers) {
          <div class="mb-2"><span class="badge bg-dark me-2">@s</span>
          @foreach (var e in Model.Eps.Where(x => x.ServerSlug == s).Take(60)) {
            <a class="btn btn-outline-light btn-sm m-1 ep-btn" href="/xem-phim/@Model.Film.Slug?server=@s&ep=@e.EpIndex">@e.EpIndex</a>
          }</div>
        }
      } else { <div class="alert alert-warning mt-3">Chưa có nguồn phát — chờ crawler cập nhật.</div> }
    </div>
  </div>
</div>

@model (TvWeb.Models.Film Film, List<TvWeb.Models.Episode> Eps, TvWeb.Models.Episode Cur)
@{ ViewData["Title"] = "Xem " + Model.Film.TitleVi + " - Tập " + Model.Cur.EpIndex; var servers = (List<string>)ViewBag.Servers; var server = (string)ViewBag.Server; }
<div class="container-fluid px-3 px-lg-4 mt-3">
  <h4>@Model.Film.TitleVi <small class="text-secondary">— Tập @Model.Cur.EpIndex (@server)</small></h4>
  <div class="player-wrap">
    @if (!string.IsNullOrEmpty(Model.Cur.M3u8Url)) {
      <video id="player" class="video-js vjs-big-play-centered" controls preload="auto" poster="@Model.Film.Poster" data-setup='{}'>
        <source src="@Model.Cur.M3u8Url" type="application/x-mpegURL" />
      </video>
    } else if (!string.IsNullOrEmpty(Model.Cur.EmbedUrl)) {
      <div class="ratio ratio-16x9"><iframe src="@Model.Cur.EmbedUrl" allowfullscreen allow="autoplay; encrypted-media; fullscreen" referrerpolicy="no-referrer"></iframe></div>
    } else {
      <div class="alert alert-warning">Chưa có link phát cho tập này.</div>
    }
  </div>
  <div class="mt-3">
    <span class="me-2">Máy chủ:</span>
    @foreach (var s in servers) { <a class="btn @(s==server?"btn-danger":"btn-outline-light") btn-sm me-1" href="/xem-phim/@Model.Film.Slug?server=@s">@s</a> }
  </div>
  <div class="mt-2 ep-list">
    @foreach (var e in Model.Eps.Where(x => x.ServerSlug == server)) {
      <a class="btn @(e.EpIndex==Model.Cur.EpIndex?"btn-danger":"btn-outline-light") btn-sm m-1 ep-btn" data-ep="@e.EpIndex" href="/xem-phim/@Model.Film.Slug?server=@server&ep=@e.EpIndex">@e.EpIndex</a>
    }
  </div>
  <a class="btn btn-link text-secondary mt-2" href="/phim/@Model.Film.Slug">← Chi tiết phim</a>
</div>
@section Scripts { <script>TvWeb.rememberEp("@Model.Film.Slug", "@server", "@Model.Cur.EpIndex");</script> }

