{"content":":root{--bg:#0b0e14;--card:#161b26;--txt:#e8ecf3}
body{background:var(--bg);color:var(--txt);font-family:system-ui,Roboto,"Segoe UI",Arial,sans-serif}
.tv-nav{background:rgba(10,12,18,.92)!important;backdrop-filter:blur(8px)}
.tv-search{background:#1c2333;border-color:#2c3650;color:#fff}
.row-title{font-weight:700;margin:8px 0 12px}
/* horizontal rail on desktop, grid on mobile */
.film-row{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}
@media(min-width:1100px){.film-row{display:flex;overflow-x:auto;padding-bottom:8px}.film-row .film-card{flex:0 0 180px}}
.film-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:14px}
.film-card{color:#fff;text-decoration:none;border-radius:10px;outline:none}
.film-card:focus-visible{box-shadow:0 0 0 3px #e50914}
.poster-wrap{position:relative;border-radius:10px;overflow:hidden;background:#000;aspect-ratio:2/3}
.poster-wrap img{width:100%;height:100%;object-fit:cover;display:block}
.badge-imdb{position:absolute;top:6px;left:6px;background:#f5c518;color:#000;font-size:11px;font-weight:700;padding:2px 6px;border-radius:6px}
