"""Find the XHR API behind client-rendered listing pages."""
import re
import httpx

BASE = "https://onflix.lat"
H = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0",
     "Referer": BASE + "/"}

with httpx.Client(timeout=30, follow_redirects=True, headers=H) as c:
    # 1) chu-de pages — maybe server rendered?
    for u in ["/chu-de/phim-dang-chieu", "/chu-de/de-xuat-cho-ban",
              "/the-loai/hanh-dong", "/phim-han?page=2", "/phim-han?page=2".replace("?page=2", "/2"),
              "/quoc-gia/han-quoc"]:
        try:
            r = c.get(BASE + u)
            s = set(re.findall(r"/phim/([\w\-]+)", r.text)) | set(re.findall(r"\\/phim\\/([\w\-]+)", r.text))
            s -= {"le", "bo", "han", "trung", "au-my"}
            print(f"{r.status_code} {len(r.text):>7} {u} -> {len(s)} slugs")
        except Exception as ex:
            print(f"ERR {u}: {ex}")
    # 2) fetch JS chunks of kham-pha to find API URLs
    r = c.get(BASE + "/kham-pha")
    chunks = sorted(set(re.findall(r'/_next/static/chunks/[\w./\-]+\.js', r.text)))
    print(f"--- {len(chunks)} js chunks on /kham-pha")
    apis = set()
    for ch in chunks[:25]:
        try:
            j = c.get(BASE + ch)
            for m in re.finditer(r'["\'`](/(?:api|v\d|search|tim-kiem|kham-pha|phim)[^"\'`\s\\]*)', j.text):
                apis.add(m.group(1))
        except Exception as ex:
            print(f"chunk ERR {ch}: {ex}")
    print("--- candidate API paths in JS:")
    for a in sorted(apis)[:60]:
        print("   ", a)

