"""Grep JS chunks for detail/episode API paths."""
import re
import httpx

H = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0",
     "Referer": "https://onflix.lat/"}

with httpx.Client(timeout=30, headers=H) as c:
    pages = ["/kham-pha", "/phim/bac-si-x-mafia-ao-trang",
             "/xem-phim/bac-si-x-mafia-ao-trang/vietsub-sn/vietsub/1"]
    chunks = set()
    htmls = {}
    for p in pages:
        r = c.get("https://onflix.lat" + p)
        htmls[p] = r.text
        chunks |= set(re.findall(r'/_next/static/chunks/[\w./\-]+\.js', r.text))
    print(f"{len(chunks)} unique chunks")
    paths = set()
    for ch in sorted(chunks):
        try:
            j = c.get("https://onflix.lat" + ch).text
            for m in re.finditer(r'[\"\']/api/[a-zA-Z0-9\-_/{}:$]+', j):
                paths.add(m.group(0))
            for m in re.finditer(r'baseURL:\s*[\"`]([^\"`]+)', j):
                paths.add("BASE:" + m.group(1))
        except Exception:
            pass
    print("--- /api paths in JS:")
    for p in sorted(paths):
        print("   ", p[:140])

