{"content":""""Probe search endpoints + kham-pha query pagination."""
import re
import httpx

BASE = "https://onflix.lat"
H = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0",
     "Referer": BASE + "/"}


def slugs(html):
    s = set(re.findall(r"/phim/([\w\-]+)", html)) | set(re.findall(r"\\/phim\\/([\w\-]+)", html))
    return s - {"le", "bo", "han", "trung", "au-my"}


with httpx.Client(timeout=30, follow_redirects=True, headers=H) as c:
    tests = [
        "/tim-kiem?q=a", "/tim-kiem?q=yeu", "/search?q=a", "/search?q=yeu",
        "/kham-pha?page=2", "/kham-pha?page=1", "/kham-pha?sort=moi-nhat",
        "/kham-pha?page=2&sort=moi-nhat",
        "/phim-han?page=2",
    ]
    for u in tests:
        try:
            r = c.get(BASE + u)
            s = slugs(r.text)
            print(f"{r.status_code} {len(r.text):>7} {u} -> {len(s)} slugs")
            if s:
                print("   ", sorted(s)[:6])
        except Exception as ex:
            print(f"ERR {u}: {ex}")
    # compare page1 vs page2 of phim-han
    a = slugs(c.get(BASE + "/phim-han").text)
    b = slugs(c.get(BASE + "/phim-han?page=2").text)
    print("han p1:", len(a), "p2:", len(b), "overlap:", len(a & b))
