{"content":""""Grep JS chunks for fetch URLs / backend API hosts."""
import re
import httpx

BASE = "https://onflix.lat"
H = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) Chrome/126.0",
     "Referer": BASE + "/"}

with httpx.Client(timeout=30, follow_redirects=True, headers=H) as c:
    r = c.get(BASE + "/kham-pha")
    chunks = sorted(set(re.findall(r'/_next/static/chunks/[\w./\-]+\.js', r.text)))
    hits = set()
    for ch in chunks:
        try:
            j = c.get(BASE + ch).text
            for m in re.finditer(r'fetch\(\s*[\"\`]([^\"\`]+)', j):
                hits.add(m.group(1))
            for m in re.finditer(r'https?://[a-zA-Z0-9.\-]+\.[a-z]{2,}(?:/[^\s\"\'\`\\]*)?', j):
                u = m.group(0)
                if any(k in u for k in ("api", "search", "phim", "movie", "film", "onflix")):
                    hits.add(u)
        except Exception as ex:
            print(f"ERR {ch}: {ex}")
    print("--- fetch/API URLs found:")
    for h in sorted(hits)[:60]:
        print("   ", h[:160])
    # also: what data is embedded in /phim-han SSR html? check __next_f for JSON with slug
    h2 = c.get(BASE + "/phim-han").text
    print("--- phim-han: has __next_f:", "__next_f" in h2, "| plain /phim/ count:", h2.count("/phim/"))
    hk = c.get(BASE + "/kham-pha").text
    print("--- kham-pha: has __next_f:", "__next_f" in hk, "| plain /phim/ count:", hk.count("/phim/"))
